import os
from azure.cognitiveservices.speech import SpeechConfig

def get_speech_config():
    speech_key = os.getenv('AZURE_SPEECH_KEY')
    service_region = os.getenv('AZURE_SPEECH_REGION')
    return SpeechConfig(subscription=speech_key, region=service_region)

from azure.cognitiveservices.speech import SpeechSynthesisOutputFormat

def get_default_synthesis_format() -> SpeechSynthesisOutputFormat:
    return SpeechSynthesisOutputFormat.Audio16Khz32KBitRateMonoMp3

import re

def check_safety(text: str) -> bool:
    # Placeholder for actual safety check implementation
    return not re.search(r'\b(badword1|badword2)\b', text, re.IGNORECASE)
